package com.bank.trade;

import jakarta.validation.Valid;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;
import java.util.List;

@RestController
@RequestMapping("/api/v1/portfolios")
public class TradeController {

    // Kết hợp cả 3 annotation chuẩn mực trong một REST Controller
    @PostMapping("/{portfolioId}/orders")
    public ResponseEntity<OrderReceipt>
    submitOrder(
        @PathVariable("portfolioId") Long portfolioId, // Định danh tài nguyên từ URI path
        @RequestParam(name = "dryRun", defaultValue = "false") boolean dryRun, // Flag từ Query string
        @Valid @RequestBody CreateOrderCommand command // Dữ liệu từ Request Body
    ) {
        OrderReceipt receipt = new OrderReceipt(portfolioId, command.symbol(), command.amount(), dryRun);
        return ResponseEntity.ok(receipt);
    }
}

record CreateOrderCommand(@NotBlank String symbol, @Min(1) BigDecimal amount) {}
record OrderReceipt(Long portfolioId, String symbol, BigDecimal amount, boolean dryRun) {}

package com.bank.architecture;

import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Repository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

// 1. Tầng Repository: Tự động dịch chuyển vendor exceptions -> DataAccessException
@Repository
class CustomAccountRepository {
    public void persistRawRecord() {
        // Nếu ném HibernateException / SQLException, Spring tự động bọc thành DataAccessException
    }
}

// 2. Tầng Service: Chứa Transaction Boundary và Business Logic
@Service
public class AccountTransferService {
    private final CustomAccountRepository repository;

    public AccountTransferService(CustomAccountRepository repository) {
        this.repository = repository;
    }

    @Transactional
    public void executeTransfer() {
        try {
            repository.persistRawRecord();
        } catch (DataAccessException ex) {
            // Bắt ngoại lệ thống nhất, không bị phụ thuộc vào driver JDBC cụ thể
            throw new RuntimeException("Database operation failed safely", ex);
        }
    }
}

