package com.bank.ecommerce.domain;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;

@Entity
@Table(name = "orders")
public class CustomerOrder {
    @Id
    // Khuyến nghị: Dùng SEQUENCE để hỗ trợ JDBC Batching tốt hơn IDENTITY
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "order_seq_gen")
    @SequenceGenerator(name = "order_seq_gen", sequenceName = "orders_seq", allocationSize = 50)
    private Long id;

    private String orderNumber;

    // Luôn đặt FetchType.LAZY và dùng mappedBy cho Inverse Side
    @OneToMany(mappedBy = "order", cascade = CascadeType.ALL, orphanRemoval = true, fetch = FetchType.LAZY)
    private List<OrderItem> items = new ArrayList<>();

    public void addItem(OrderItem item) {
        items.add(item);
        item.setOrder(this); // Đồng bộ cả 2 chiều trong bộ nhớ
    }
}

@Entity
@Table(name = "order_items")
class OrderItem {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE, generator = "item_seq_gen")
    @SequenceGenerator(name = "item_seq_gen", sequenceName = "order_items_seq", allocationSize = 50)
    private Long id;

    // Owning side: Nơi chứa Foreign Key thực tế trong bảng DB
    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "order_id", nullable = false)
    private CustomerOrder order;

    private BigDecimal price;

    public void setOrder(CustomerOrder order) { this.order = order; }
}

