package com.bank.payment.service;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.io.IOException;

class InsufficientBalanceException extends Exception { // Checked Exception!
    public InsufficientBalanceException(String msg) { super(msg); }
}

@Service
public class MoneyTransferService {

    // NGUY HIỂM: Ném InsufficientBalanceException vẫn COMMIT dữ liệu DB!
    // @Transactional

    // CHUẨN KIẾN TRÚC: Luôn chỉ định rollbackFor với mọi Exception nếu dùng Checked Exceptions
    @Transactional(rollbackFor = Exception.class)
    public void executeTransfer(String fromAcc, String toAcc, double amount) throws InsufficientBalanceException {
        // 1. Trừ tiền tài khoản nguồn
        // 2. Gặp sự cố ném Checked Exception -> Nhờ có rollbackFor = Exception.class, DB sẽ rollback an toàn
        if (amount > 1000) {
            throw new InsufficientBalanceException("Limit exceeded");
        }
    }
}

