package com.bank.account.repository;

import com.bank.account.domain.Account;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;
import java.util.List;

public interface AccountRepository extends JpaRepository<Account, Long> {

    // 1. Derived query method: Tối ưu cho thao tác đơn giản
    List<Account> findByStatusAndCurrency(String status, String currency);

    // 2. JPQL @Query: Hướng đối tượng, độc lập database vendor
    @Query("SELECT a FROM Account a WHERE a.balance > :minBalance ORDER BY a.createdAt DESC")
    List<Account> findHighBalanceAccounts(@Param("minBalance") double minBalance);

    // 3. Native Query: Sử dụng PostgreSQL CTE & Window Functions
    @Query(value = """
        WITH RankedTransactions AS (
            SELECT account_id, amount, ROW_NUMBER() OVER (PARTITION BY account_id ORDER BY created_at DESC) as rn
            FROM transactions
        )
        SELECT a.id as id, a.account_number as accountNumber 
        FROM accounts a JOIN RankedTransactions rt ON a.id = rt.account_id WHERE rt.rn = 1
        """, nativeQuery = true)
    List<AccountSummaryProjection> findLatestTransactionSummaries();
}

interface AccountSummaryProjection {
    Long getId();
    String getAccountNumber();
}

