// Business service hoàn toàn độc lập với việc khởi tạo SmsNotificationService
class FraudAlertManager {
    private final NotificationService notificationService;

    // DI thông qua Constructor: High testability & Loose coupling
    public FraudAlertManager(NotificationService notificationService) {
        this.notificationService = notificationService;
    }

    public void triggerAlarm() {
        notificationService.sendAlert("Potential fraudulent transaction detected!");
    }
}

@Configuration
class AppContainerConfig {
    @Bean
    public NotificationService notificationService() { return new SmsNotificationService(); }

    @Bean
    public FraudAlertManager fraudAlertManager(NotificationService svc) {
        return new FraudAlertManager(svc); // Container tự động resolve và inject
    }
}

