package com.bank.marketdata;

import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;
import reactor.core.publisher.Flux;
import reactor.core.publisher.Mono;
import java.time.Duration;

@RestController
public class MarketFeedController {

    // 1. Mono: Trả về 0 hoặc 1 kết quả (REST API bất đồng bộ)
    @GetMapping("/api/v1/ticker/latest")
    public Mono<StockQuote> getLatestQuote() {
        return Mono.just(new StockQuote("AAPL", 189.50));
    }

    // 2. Flux + Backpressure + Server-Sent Events (SSE): Stream realtime an toàn
    @GetMapping(value = "/api/v1/ticker/stream", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public Flux<StockQuote> streamQuotes() {
        return Flux.interval(Duration.ofMillis(100))
            .map(seq -> new StockQuote("AAPL", 189.50 + Math.random()))
            .onBackpressureDrop(dropped -> System.out.println("Dropped quote: " + dropped))
            .take(1000); // Giới hạn số lượng emit
    }
}

