    // Kịch bản: Stateless REST API dùng JWT -> An toàn để tắt CSRF hoàn toàn
    @Bean
    public SecurityFilterChain apiSecurityFilterChain(HttpSecurity http) throws Exception {
        return http
            .csrf(csrf -> csrf.disable()) // Tắt CSRF vì client dùng Bearer Token, không dùng Session Cookie
