package com.bank.health;

import org.springframework.boot.actuate.health.Health;
import org.springframework.boot.actuate.health.HealthIndicator;
import org.springframework.stereotype.Component;
import java.net.Socket;

@Component("swiftGatewayHealthIndicator")
public class SwiftGatewayHealthIndicator implements HealthIndicator {

    private static final String SWIFT_HOST = "swift-gateway.bank.internal";
    private static final int SWIFT_PORT = 9999;

    @Override
    public Health health() {
        // Kiểm tra kết nối TCP với timeout ngắn (1.5 giây)
        try (Socket socket = new Socket()) {
            socket.connect(new java.net.InetSocketAddress(SWIFT_HOST, SWIFT_PORT), 1500);
            return Health.up()
                .withDetail("target", SWIFT_HOST)
                .withDetail("latencyMs", 12)
                .build();
        } catch (Exception ex) {
            // Báo DOWN kèm thông tin lỗi chi tiết giúp đội SRE xử lý sự cố ngay lập tức
            return Health.down(ex)
                .withDetail("target", SWIFT_HOST)
                .withDetail("error", "Failed to establish TCP handshake with Swift Gateway")
                .build();
        }
    }
}

