package com.bank.kafka.integration;

import org.apache.kafka.clients.consumer.ConsumerRecord;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.support.Acknowledgment;
import org.springframework.stereotype.Service;

@Service
public class PaymentOrderMessagingService {
    private final KafkaTemplate<String, String> kafkaTemplate;

    public PaymentOrderMessagingService(KafkaTemplate<String, String> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    // 1. PRODUCER: Gửi message bất đồng bộ kèm non-blocking callback
    public void publishOrderEvent(String orderId, String payload) {
        kafkaTemplate.send("payment-orders", orderId, payload)
            .whenComplete((result, ex) -> {
                if (ex == null) {
                    System.out.println("Sent offset: " + result.getRecordMetadata().offset());
                } else {
                    System.err.println("Kafka send error: " + ex.getMessage());
                }
            });
    }

    // 2. CONSUMER: Tiếp nhận và xác nhận offset thủ công an toàn
    @KafkaListener(topics = "payment-orders", groupId = "payment-ledger-group")
    public void consumePaymentOrder(ConsumerRecord<String, String> record, Acknowledgment ack) {
        try {
            System.out.println("Processing order key: " + record.key() + ", value: " + record.value());
            // Xử lý nghiệp vụ lưu database...
            ack.acknowledge(); // Chỉ commit offset khi nghiệp vụ hoàn tất thành công!
        } catch (Exception ex) {
            throw ex; // Ném lỗi để DefaultErrorHandler kích hoạt retry & DLT
        }
    }
}

