package com.bank.aop.audit;

import org.aspectj.lang.ProceedingJoinPoint;
import org.aspectj.lang.annotation.Around;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Pointcut;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;
import java.lang.annotation.*;

@Target(ElementType.METHOD)
@Retention(RetentionPolicy.RUNTIME)
@interface AuditedTransaction {
    String action();
}

@Aspect
@Component
public class TransactionAuditAspect {
    private static final Logger log = LoggerFactory.getLogger(TransactionAuditAspect.class);

    // 1. Pointcut: Khớp với bất kỳ method nào có gắn @AuditedTransaction
    @Pointcut("@annotation(auditedAnnotation)")
    public void auditedActionPointcut(AuditedTransaction auditedAnnotation) {}

    // 2. Advice @Around: Chặn trước, đo thời gian thực thi, bắt lỗi và ghi log audit
    @Around(value = "auditedActionPointcut(auditedAnnotation)", argNames = "joinPoint,auditedAnnotation")
    public Object auditExecution(ProceedingJoinPoint joinPoint, AuditedTransaction auditedAnnotation) throws Throwable {
        long start = System.currentTimeMillis();
        String methodName = joinPoint.getSignature().toShortString();
        log.info("AUDIT START: Action [{}] on method [{}]", auditedAnnotation.action(), methodName);

        try {
            Object result = joinPoint.proceed(); // Thực thi method gốc
            long duration = System.currentTimeMillis() - start;
            log.info("AUDIT SUCCESS: Action [{}] completed in {} ms", auditedAnnotation.action(), duration);
            return result;
        } catch (Throwable ex) {
            log.error("AUDIT FAILURE: Action [{}] failed with error: {}", auditedAnnotation.action(), ex.getMessage());
            throw ex; // Re-throw ngoại lệ để bảo toàn luồng xử lý lỗi
        }
    }
}

