    @Transactional
    public void completeTransfer(Long transferId, String email) {
        // 1. Cập nhật số dư trong Database
        // 2. Publish event: Chưa gửi email ngay lập tức!
        eventPublisher.publishEvent(new MoneyTransferredEvent(transferId, email));
        // Nếu có ngoại lệ ở đây -> Transaction Rollback -> Event bên dưới KHÔNG BAO GIỜ CHẠY!
    }
}

@Service
class NotificationDispatcher {
    // Chỉ chạy KHI VÀ CHỈ KHI Database Transaction đã COMMIT thành công 100%
    @TransactionalEventListener(phase = TransactionPhase.AFTER_COMMIT)
    public void onTransferSuccess(MoneyTransferredEvent event) {
        System.out.println("Transaction committed safely. Sending receipt email to: " + event.recipientEmail());
    }
}

