package com.bank.orm.lifecycle;

import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class EntityLifecycleDemoService {

    @PersistenceContext
    private EntityManager entityManager;

    @Transactional
    public void demonstrateTransitions() {
        // 1. TRANSIENT: Vừa tạo mới, chưa có ID trong DB
        BankAccount account = new BankAccount("ACC-001", 1000.0);

        // 2. MANAGED: Gắn vào Persistence Context, có ID, Dirty Checking bắt đầu theo dõi
        entityManager.persist(account);

        account.setBalance(1500.0); // Tự động cập nhật DB khi commit mà KHÔNG cần gọi update()!

        // 3. DETACHED: Tách khỏi Persistence Context
        entityManager.detach(account);
        account.setBalance(9999.0); // Không còn được theo dõi, DB vẫn giữ 1500.0

        // 4. MANAGED lại qua MERGE
        BankAccount managedAgain = entityManager.merge(account);

        // 5. REMOVED: Đánh dấu xóa khỏi DB
        entityManager.remove(managedAgain);
    }
}

class BankAccount {
    private String number;
    private double balance;
    public BankAccount(String n, double b) { this.number = n; this.balance = b; }
    public void setBalance(double b) { this.balance = b; }
}

