import java.net.URI;
import java.time.Instant;
import java.util.UUID;

@RestControllerAdvice
public class EnterpriseProblemDetailHandler {

    // Chuẩn Spring Boot 3 / RFC 9457
    @ExceptionHandler(InsufficientFundsException.class)
    public ProblemDetail handleInsufficientFunds(InsufficientFundsException ex) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, ex.getMessage());
        problem.setTitle("Insufficient Account Balance");
        problem.setType(URI.create("https://api.bank.com/errors/insufficient-funds"));
        problem.setInstance(URI.create("/api/v1/transfers"));

        // Bổ sung các extension fields an toàn
        problem.setProperty("timestamp", Instant.now());
        problem.setProperty("errorReferenceCode", "ERR-" + UUID.randomUUID().toString().substring(0, 8));
        return problem;
    }
}

class InsufficientFundsException extends RuntimeException {
