package com.bank.orm.dirtycheck;

import com.bank.domain.Account;
import com.bank.repository.AccountRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class AccountBalanceAdjustmentService {
    private final AccountRepository accountRepository;

    public AccountBalanceAdjustmentService(AccountRepository accountRepository) {
        this.accountRepository = accountRepository;
    }

    @Transactional
    public void applyInterest(Long accountId, double rate) {
        // 1. Entity chuyển sang trạng thái MANAGED, snapshot được lưu trong L1 Cache
        Account account = accountRepository.findById(accountId)
            .orElseThrow(() -> new IllegalArgumentException("Account not found"));

        // 2. Chỉ thay đổi setter bình thường
        account.setBalance(account.getBalance() * (1 + rate));

        // 3. KHÔNG CẦN GỌI: accountRepository.save(account); !!
        // Khi ra khỏi method, Hibernate Session Flush tự động phát hiện dirty và sinh SQL UPDATE!
    }
}

