package com.bank.orm.identity;

import jakarta.persistence.*;
import org.hibernate.Hibernate;
import java.util.Objects;
import java.util.UUID;

@Entity
public class SecureAccount {
    @Id @GeneratedValue
    private Long id;

    // GIẢI PHÁP TỐI THƯỢNG: Business Key / Natural ID bất biến tạo ngay khi khởi tạo
    @Column(nullable = false, unique = true, updatable = false)
    private final String businessKey = UUID.randomUUID().toString();

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || Hibernate.getClass(this) != Hibernate.getClass(o)) return false;
        SecureAccount that = (SecureAccount) o;
        // So sánh bằng Natural Key bất biến an toàn trước mọi trạng thái vòng đời
        return Objects.equals(businessKey, that.businessKey);
    }

    @Override
    public int hashCode() {
        return Objects.hash(businessKey);
    }
}

package com.bank.security.flow;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.authentication.AuthenticationManager;
import org.springframework.security.authentication.ProviderManager;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.security.crypto.password.PasswordEncoder;
import java.util.List;

@Configuration
public class AuthenticationFlowArchitectureConfig {

    // Minh họa tường minh luồng liên kết các thành phần xác thực của Spring Security
    @Bean
    public AuthenticationManager customAuthenticationManager(
            UserDetailsService userDetailsService,
            PasswordEncoder passwordEncoder) {

        DaoAuthenticationProvider authProvider = new DaoAuthenticationProvider();
        authProvider.setUserDetailsService(userDetailsService); // Bước 5: Load UserDetails
        authProvider.setPasswordEncoder(passwordEncoder);       // Bước 6: Matches password
        authProvider.setHideUserNotFoundExceptions(true);        // Chống Timing Attack

        return new ProviderManager(List.of(authProvider));     // Bước 4: ProviderManager điều phối
    }
}

