import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.core.annotation.Order;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.oauth2.core.AuthorizationGrantType;
import org.springframework.security.oauth2.core.ClientAuthenticationMethod;
import org.springframework.security.oauth2.server.authorization.client.InMemoryRegisteredClientRepository;
import org.springframework.security.oauth2.server.authorization.client.RegisteredClient;
import org.springframework.security.oauth2.server.authorization.client.RegisteredClientRepository;
import org.springframework.security.oauth2.server.authorization.config.annotation.web.configuration.OAuth2AuthorizationServerConfiguration;
import org.springframework.security.web.SecurityFilterChain;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.interfaces.RSAPrivateKey;
import java.security.interfaces.RSAPublicKey;
import java.util.UUID;

@Configuration
public class SpringAuthServerOAuth21Config {

    @Bean
    @Order(1)
    public SecurityFilterChain authServerSecurityFilterChain(HttpSecurity http) throws Exception {
        OAuth2AuthorizationServerConfiguration.applyDefaultSecurity(http);
        return http.formLogin(Customizer.withDefaults()).build();
    }

    @Bean
    public RegisteredClientRepository registeredClientRepository() {
        // Chuẩn OAuth 2.1: Bắt buộc requireAuthorizationConsent và requireProofKey (PKCE)
        RegisteredClient spaClient = RegisteredClient.withId(UUID.randomUUID().toString())
            .clientId("bank-mobile-app")
            .clientAuthenticationMethod(ClientAuthenticationMethod.NONE) // Public Client
            .authorizationGrantType(AuthorizationGrantType.AUTHORIZATION_CODE)
            .authorizationGrantType(AuthorizationGrantType.REFRESH_TOKEN)
            .redirectUri("https://app.bank.com/oauth/callback")
            .scope("accounts:read")
            .clientSettings(org.springframework.security.oauth2.server.authorization.settings.ClientSettings.builder()
                .requireProofKey(true) // BẮT BUỘC PKCE theo chuẩn OAuth 2.1
                .requireAuthorizationConsent(true)
                .build())
            .build();
        return new InMemoryRegisteredClientRepository(spaClient);
    }
}

package com.bank.resourceserver.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

// Trong application.yml của Resource Server chỉ cần chỉ định JWKS endpoint của Auth Server:
// spring.security.oauth2.resourceserver.jwt.jwk-set-uri: https://auth.bank.com/oauth2/jwks

@Configuration
@EnableMethodSecurity
public class ResourceServerSecurityConfig {

    // Cấu hình phía RESOURCE SERVER: Hoàn toàn phi trạng thái, xác thực token qua JWKS
    @Bean
    public SecurityFilterChain resourceServerFilterChain(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/v1/public/**").permitAll()
                .requestMatchers("/api/v1/transactions/**").hasAuthority("SCOPE_payment:write")
                .anyRequest().authenticated()
            )
            .oauth2ResourceServer(oauth2 -> oauth2.jwt(Customizer.withDefaults())) // Kích hoạt JWT Validator
            .build();
    }
}

