// 2. SPRING WEBFLUX: Reactive Streaming non-blocking hoàn hảo cho High-Concurrency Gateway
import org.springframework.web.bind.annotation.*;
import reactor.core.publisher.Mono;

@RestController
public class ReactiveWebFluxController {
    private final ReactivePaymentPort paymentPort;

    public ReactiveWebFluxController(ReactivePaymentPort paymentPort) {
        this.paymentPort = paymentPort;
    }

    @PostMapping("/flux/payments")
    public Mono<PaymentReceipt> processReactivePayment(@RequestBody Mono<PaymentCommand> command) {
        // Toàn bộ pipeline là non-blocking event-driven
        return command
            .flatMap(paymentPort::execute)
            .doOnError(ex -> System.err.println("Payment failed: " + ex.getMessage()));
    }
}

interface ReactivePaymentPort { Mono<PaymentReceipt> execute(PaymentCommand cmd); }
record PaymentCommand(String id, double amount) {}
record PaymentReceipt(String id, String status) {}

package com.bank.testing.tradeoff;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.testcontainers.service.connection.ServiceConnection;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.Container;
import org.testcontainers.junit.jupiter.Testcontainers;
import javax.sql.DataSource;
import static org.assertj.core.api.Assertions.assertThat;

// CHIẾN LƯỢC ENTERPRISE: Dùng Testcontainers bảo đảm parity 100% với PostgreSQL Production
@SpringBootTest
@Testcontainers
class ProductionFidelityIntegrationTest {

    // Tối ưu hóa: Khởi tạo 1 container duy nhất dùng chung cho toàn bộ test suite
    @Container
    @ServiceConnection
    static PostgreSQLContainer<?> postgres = new PostgreSQLContainer<>("postgres:16-alpine")
        .withDatabaseName("core_bank_test")
        .withReuse(true); // Tái sử dụng container giữa các lần chạy test

    @Autowired
    private DataSource dataSource;

    @Test
    void shouldVerifyPostgreSqlSpecificJsonbCapabilities() throws Exception {
        assertThat(postgres.isRunning()).isTrue();
        // Kiểm tra câu lệnh dùng cú pháp PostgreSQL đặc thù mà H2 hoàn toàn không hỗ trợ
        var rs = dataSource.getConnection().createStatement().executeQuery("SELECT '{\"status\": \"OK\"}'::jsonb");
        assertThat(rs.next()).isTrue();
    }
}
